137:   const userId = useCurrentUser()?.id ?? null;
138:   const userIdRef = useRef(userId);
139:   userIdRef.current = userId;
140:   /** Rule 19 key for the CURRENT coach intent; replayed across retries of it. */
141:   const idempotencyKeyRef = useRef<string | null>(null);
142:   /** False until the durable mirror has been consulted exactly once per mount. */
143:   const hydratedRef = useRef(false);
144:   /** A start() that arrived before hydration finished, deferred not dropped. */
145:   const pendingStartRef = useRef(false);
146:   const startRef = useRef<(() => void) | null>(null);
147: 
148:   const clearTimers = useCallback(() => {
149:     if (pollTimerRef.current) clearTimeout(pollTimerRef.current);
150:     pollTimerRef.current = null;
151:   }, []);
152: 
153:   /**
154:    * Move to a codeless terminal/reset status and tear down timers.
155:    * `supportReference` is the server's correlation id for the request that
156:    * caused this transition, when it gave one; every non-error transition clears
157:    * it so a stale reference can never be attached to a later failure.
158:    */
159:   const go = useCallback(
160:     (next: PairingStatus, supportReference: string | null = null) => {
161:       clearTimers();
162:       // Ending this session frees the poll single-flight guard so the next
163:       // session can poll; a still-outstanding poll from the old session is
164:       // discarded by its code check (below) and cannot re-stomp the guard.
165:       pollInFlightRef.current = false;
166:       codeRef.current = null;
167:       // No status reached here still owns a code, so the durable mirror is stale
168:       // by definition — including 'minting', where a fresh mint supersedes it.
169:       const uid = userIdRef.current;
170:       if (uid) void clearImportPairingMirror(uid);
171:       // Retire the Rule 19 key on every outcome EXCEPT a transient network
172:       // 'failed' (and the 'minting' transition): a retry after a lost response is
173:       // the SAME coach intent and must replay the same key, whereas a retry after
174:       // paired/expired/cancelled/auth/unavailable is a genuinely new intent.
175:       if (next !== 'failed' && next !== 'minting') idempotencyKeyRef.current = null;
176:       statusRef.current = next;
177:       if (mountedRef.current) setState({ status: next, code: null, supportReference });
178:     },
179:     [clearTimers],

186:   const doPoll = useCallback(async () => {
187:     if (!mountedRef.current || pausedRef.current) return;
188:     if (statusRef.current !== 'waiting') return;
189:     // Single-flight: a /status request is already outstanding. A foreground
190:     // resume (or any re-entry) while one poll is in flight must NOT fire a
191:     // second concurrent request; the outstanding poll reschedules the next one.
192:     if (pollInFlightRef.current) return;
193:     const code = codeRef.current;
194:     if (!code) return;
195:     pollInFlightRef.current = true;
196:     try {
197:       const res = await extensionPairApi.status(code);
198:       // Discard a late/stale result: unmounted, session moved off 'waiting', or
199:       // the code was abandoned/re-minted (cancel→retry) while this poll was out.
200:       if (!mountedRef.current || statusRef.current !== 'waiting' || codeRef.current !== code) return;
201:       const decoded = decodePairStatus(res.data?.status ?? '');
202:       if (decoded === 'paired') {
203:         go('paired');
204:         track(AnalyticsEvents.IMPORT_PAIRED, { platform: platformRef.current });
205:         return;
206:       }
207:       if (decoded === 'expired') {
208:         go('expired');
209:         track(AnalyticsEvents.IMPORT_PAIRING_EXPIRED, { platform: platformRef.current });
210:         return;
211:       }
212:       // 'pending' or (fail-closed) 'unknown' → keep waiting, back off, never promote.
213:       failureCountRef.current = 0;
214:       pollDelayRef.current = Math.min(pollDelayRef.current * POLL_BACKOFF, POLL_MAX_MS);
215:       pollTimerRef.current = setTimeout(doPoll, pollDelayRef.current);
216:     } catch (err) {
217:       if (!mountedRef.current || statusRef.current !== 'waiting' || codeRef.current !== code) return;
218:       const s = axiosStatus(err);
219:       const ref = extractRequestId(err);
220:       if (s === 401 || s === 403) {
221:         go('authExpired', ref);
222:         emitFailed('auth');
223:         return;
224:       }
225:       if (s === 404) {
226:         go('unavailable', ref);
227:         emitFailed('unavailable');
228:         return;
229:       }
230:       failureCountRef.current += 1;
231:       if (failureCountRef.current >= MAX_POLL_FAILURES) {
232:         go('failed', ref);
233:         emitFailed('network');
234:         return;
235:       }
236:       pollDelayRef.current = Math.min(pollDelayRef.current * POLL_BACKOFF, POLL_MAX_MS);
237:       pollTimerRef.current = setTimeout(doPoll, pollDelayRef.current);
238:     } finally {
239:       // Release only if this invocation still owns the live session; a superseded
240:       // (stale) poll must not clear a guard a fresh session's poll now holds.
241:       if (codeRef.current === code) pollInFlightRef.current = false;
242:     }
243:   }, [go, emitFailed]);

245:   const start = useCallback(async () => {
246:     if (!enabled) return; // fail closed: no network path when the feature is OFF
247:     const slug = platformRef.current;
248:     if (!slug) return;
249:     if (mintInFlightRef.current) return; // single-flight
250:     if (statusRef.current === 'minting' || statusRef.current === 'waiting') return; // no duplicate intent
251:     // Minting before the mirror has been read could open a second server-side
252:     // session on top of one the coach already has. Defer, never drop.
253:     if (!hydratedRef.current) {
254:       pendingStartRef.current = true;
255:       return;
256:     }
257:     let key = idempotencyKeyRef.current;
258:     if (!key) {
259:       try {
260:         key = generateIdempotencyKey();
261:       } catch (err) {
262:         // No CSPRNG means no safe retry key; minting anyway risks a duplicate
263:         // session, so fail visibly instead (Rule 19 has no soft fallback).
264:         logger.warn('[useExtensionPairing] idempotency key unavailable', err);
265:         go('failed');
266:         emitFailed('network');
267:         return;
268:       }
269:       idempotencyKeyRef.current = key;
270:     }
271:     mintInFlightRef.current = true;
272:     go('minting');
273:     track(AnalyticsEvents.IMPORT_PAIRING_STARTED, { platform: slug });
274:     try {
275:       const res = await extensionPairApi.init(slug, key);
276:       // `go('minting')` set the ref, but TS narrowed it from the guard above; read fresh.
277:       // cancelled/unmounted mid-mint → discard this late result (no HTTP abort).
278:       if (!mountedRef.current || (statusRef.current as PairingStatus) !== 'minting') return;
279:       const code = res.data?.pairing_code ?? null;
280:       if (!code) {
281:         go('failed');
282:         emitFailed('network');
283:         return;
284:       }
285:       // Persist BEFORE showing the code: the coach's next action is to leave the
286:       // app, so a code on screen that is not on disk is exactly the state that
287:       // an OS kill turns into an orphaned server-side session. A write failure
288:       // is logged and the flow continues — degraded durability, not a dead flow.
289:       const uid = userIdRef.current;
290:       if (uid) {
291:         try {
292:           await writeImportPairingMirror({
293:             version: IMPORT_PAIRING_MIRROR_VERSION,
294:             userId: uid,
295:             platformId: slug,
296:             code,
297:             // Stored verbatim for provenance/support only; never clock-compared.
298:             expiresAt: res.data?.expires_at ?? '',
299:             idempotencyKey: key,
300:           });
301:         } catch (err) {
302:           logger.warn('[useExtensionPairing] mirror write failed', err);
303:         }
304:         if (!mountedRef.current || (statusRef.current as PairingStatus) !== 'minting') return;
305:       }
306:       codeRef.current = code;
307:       pollDelayRef.current = POLL_BASE_MS;
308:       failureCountRef.current = 0;
309:       statusRef.current = 'waiting';
310:       setState({ status: 'waiting', code, supportReference: null });
311:       track(AnalyticsEvents.IMPORT_PAIRING_CODE_READY, { platform: slug });
312:       pollTimerRef.current = setTimeout(doPoll, POLL_BASE_MS);

342:   useEffect(() => {
343:     let abandoned = false;
344:     void (async () => {
345:       const uid = userIdRef.current;
346:       const restored = enabled && uid ? await readImportPairingMirror(uid) : null;
347:       if (abandoned || !mountedRef.current) return;
348:       hydratedRef.current = true;
349:       if (restored && statusRef.current === 'idle') {
350:         idempotencyKeyRef.current = restored.idempotencyKey;
351:         codeRef.current = restored.code;
352:         pollDelayRef.current = POLL_BASE_MS;
353:         failureCountRef.current = 0;
354:         statusRef.current = 'waiting';
355:         setState({ status: 'waiting', code: restored.code, supportReference: null });
356:         track(AnalyticsEvents.IMPORT_PAIRING_RESTORED, { platform: restored.platformId });
357:         pollTimerRef.current = setTimeout(doPoll, 0);
358:         return;
359:       }
360:       if (pendingStartRef.current) {
361:         pendingStartRef.current = false;
362:         startRef.current?.();
363:       }
364:     })();
365:     return () => {
366:       abandoned = true;
367:     };
368:   }, [enabled, doPoll]);
