370:   const cancel = useCallback(() => {
371:     const wasActive = statusRef.current === 'minting' || statusRef.current === 'waiting';
372:     go('cancelled');
373:     if (wasActive) track(AnalyticsEvents.IMPORT_PAIRING_CANCELLED, { platform: platformRef.current });
374:   }, [go]);
