376:   // Pause polling in the background; resume on foreground. Expiry is decided by
377:   // the server /status contract on the next poll, never by a client clock.
378:   useEffect(() => {
379:     const sub = AppState.addEventListener('change', (next: AppStateStatus) => {
380:       if (next === 'active') {
381:         pausedRef.current = false;
382:         if (statusRef.current === 'waiting') {
383:           if (pollTimerRef.current) clearTimeout(pollTimerRef.current);
384:           pollTimerRef.current = setTimeout(doPoll, 0);
385:         }
386:       } else {
387:         pausedRef.current = true;
388:         clearTimers();
389:       }
390:     });
391:     return () => sub.remove();
392:   }, [doPoll, clearTimers]);
393: 
394:   // Teardown on unmount: cancel every in-flight timer, block late setState.
395:   useEffect(() => {
396:     mountedRef.current = true;
397:     return () => {
398:       mountedRef.current = false;
399:       clearTimers();
400:     };
401:   }, [clearTimers]);

58: export interface MirroredPairingSession {
59:   version: number;
60:   /** Owning coach. Also encoded in the key; kept here to detect a mismatch. */
61:   userId: string;
62:   /** `chosen_platform` slug the session was minted for. */
63:   platformId: string;
64:   /** The 6-digit code shown to the coach. Never logged, never sent to telemetry. */
65:   code: string;
66:   /** Server-authoritative ISO-8601 expiry, stored verbatim. Never compared locally. */
67:   expiresAt: string;
68:   /** Rule 19 key, replayed on every re-mint of this same intent. */
69:   idempotencyKey: string;
70: }
71: 
72: function isMirroredPairingSession(
73:   value: unknown,
74: ): value is MirroredPairingSession {
75:   if (!value || typeof value !== 'object') return false;
76:   const v = value as Record<string, unknown>;
77:   return (
78:     v.version === IMPORT_PAIRING_MIRROR_VERSION &&
79:     typeof v.userId === 'string' &&
80:     v.userId.length > 0 &&
81:     typeof v.platformId === 'string' &&
82:     v.platformId.length > 0 &&
83:     typeof v.code === 'string' &&
84:     v.code.length > 0 &&
85:     typeof v.expiresAt === 'string' &&
86:     typeof v.idempotencyKey === 'string' &&
87:     v.idempotencyKey.length > 0
88:   );
89: }
90: 
91: /**
92:  * Persist `session`, overwriting any prior session for the same coach — a coach
93:  * pairs one platform at a time, and a re-mint supersedes whatever came before.
94:  * Throws on a write failure so the caller can decide, rather than believing a
95:  * write happened that did not.
96:  */
97: export async function writeImportPairingMirror(
98:   session: MirroredPairingSession,
99: ): Promise<void> {
100:   await AsyncStorage.setItem(
101:     importPairingMirrorKey(session.userId),
102:     JSON.stringify(session),
103:   );
104: }
105: 
106: /**
107:  * Read back the pending session for `userId`, or null when there is none.
108:  * A corrupt, version-drifted, shape-drifted, or cross-user payload is discarded
109:  * (and its key deleted) rather than returned.
110:  */
111: export async function readImportPairingMirror(
112:   userId: string,
113: ): Promise<MirroredPairingSession | null> {
114:   let raw: string | null;
115:   try {
116:     raw = await AsyncStorage.getItem(importPairingMirrorKey(userId));
117:   } catch (err) {
118:     logger.warn('[importPairingMirror] read failed', err);
119:     return null;
120:   }
121:   if (raw == null) return null;
122: 
123:   let parsed: unknown;
124:   try {
125:     parsed = JSON.parse(raw);
126:   } catch (err) {
127:     logger.warn('[importPairingMirror] corrupt JSON discarded', err);
128:     await clearImportPairingMirror(userId);
129:     return null;
130:   }
131:   if (!isMirroredPairingSession(parsed)) {
132:     logger.warn('[importPairingMirror] shape or version drift discarded');
133:     await clearImportPairingMirror(userId);
134:     return null;
135:   }
136:   if (parsed.userId !== userId) {
137:     // The key says one coach, the payload says another. Never hand a coach a
138:     // session that is not theirs — discard rather than reconcile.
139:     logger.warn('[importPairingMirror] user mismatch discarded');
140:     await clearImportPairingMirror(userId);
141:     return null;
142:   }
143:   return parsed;

16: /** `expires_at` is server-authoritative ISO-8601; derive any countdown from it. */
17: export interface PairInitResponse {
18:   pairing_code: string;
19:   expires_at: string;
20: }
21: 
22: export interface PairStatusRequest {
23:   code: string;
24: }
