26: /**
27:  * Both `status` and `terminal_status` are CLOSED enums in the backend contract,
28:  * constrained per direction: pair `status` is a server-derived RESPONSE field
29:  * (OpenAPI `enum` + `PAIR_STATUSES` TS union — no `@IsIn`, nothing inbound to
30:  * validate); scout `terminal_status` is an INBOUND field (OpenAPI `enum` +
31:  * `SCOUT_TERMINAL_STATUSES` const union + class-validator `@IsIn`). Mobile still
32:  * keeps the raw string on the wire and decodes defensively rather than
33:  * blind-casting: a recognised value maps to its lifecycle member; anything else
34:  * — a future/renamed/garbled/malformed value — resolves to `'unknown'`, never an
35:  * asserted member. Forward-compatible version-skew defense, not a claim the
36:  * contract is open: `'unknown'` NEVER reads as paired, complete, or success.
37:  */
38: export type PairStatus = 'pending' | 'paired' | 'expired';
39: export type DecodedPairStatus = PairStatus | 'unknown';
40: 
41: export interface PairStatusResponse {
42:   status: string; // raw wire value — decode via decodePairStatus, never cast
43: }
44: 
45: export function decodePairStatus(raw: string): DecodedPairStatus {
46:   return raw === 'pending' || raw === 'paired' || raw === 'expired' ? raw : 'unknown';

24: export function useRosterReviewDelta(
25:   enabled: boolean = featureFlags.extensionImport,
26: ): RosterReviewDelta {
27:   const user = useCurrentUser();
28:   const userId = user?.id ?? null;
29:   const loadClients = useCoachStore((s) => s.loadClients);
30: 
31:   const baselineRef = useRef<{ userId: string; count: number } | null>(null);
32:   const userIdRef = useRef<string | null>(userId);
33:   userIdRef.current = userId;
34:   const mountedRef = useRef(true);
35:   useEffect(() => () => {
36:     mountedRef.current = false;
37:   }, []);
38: 
39:   const [delta, setDelta] = useState(0);
40: 
41:   // Load the authoritative roster, then commit only when the load demonstrably
42:   // succeeded (Rule 18: a failed load must never anchor a baseline nor move the
43:   // delta) AND the user has not changed under us (never mix one tenant's counts
44:   // into another). Re-reads baseline at resolution so a reset can't be raced.
45:   const sync = useCallback(() => {
46:     if (!enabled || !userId) return;
47:     void loadClients(userId).then(() => {
48:       if (!mountedRef.current || userIdRef.current !== userId) return;
49:       const state = useCoachStore.getState();
50:       if (state.loadError !== null) return;
51:       const count = state.clients.length;
52:       const base = baselineRef.current;
53:       if (!base || base.userId !== userId) {
54:         baselineRef.current = { userId, count };
55:         setDelta(0);
56:       } else {
57:         setDelta(Math.max(0, count - base.count));
58:       }
59:     });
60:   }, [enabled, userId, loadClients]);
61: 
62:   // Capture the baseline once per user at journey start; reset on user change /
63:   // sign-out so a second coach never inherits the first coach's baseline.
64:   useEffect(() => {
65:     if (!enabled || !userId) {
66:       baselineRef.current = null;
67:       setDelta(0);
68:       return;
69:     }
70:     if (baselineRef.current?.userId === userId) return;
71:     baselineRef.current = null;
72:     setDelta(0);
73:     sync();
74:   }, [enabled, userId, sync]);
75: 
76:   // Foreground refresh: recompute on resume, or re-capture if a prior baseline
77:   // load failed. The listener is registered once per enabled-change (calling the
78:   // latest sync via a ref) so flag-off touches no listener and re-renders never
79:   // churn subscriptions.
80:   const syncRef = useRef(sync);
81:   syncRef.current = sync;
82:   useEffect(() => {
83:     if (!enabled) return;
84:     const subscription = AppState.addEventListener('change', (next: AppStateStatus) => {
85:       if (next === 'active') syncRef.current();
86:     });
87:     return () => subscription.remove();
88:   }, [enabled]);

36: function useFamilyReconstruct(
37:   family: ReconstructFamily,
38:   coachId: string | null,
39:   enabled: boolean,
40: ): ReconstructFamilyCounts {
41:   const query = useInfiniteQuery({
42:     // coach id + page size in the key ⇒ distinct cache per coach; cursor via pageParam.
43:     queryKey: [
44:       'import',
45:       'reconstruct',
46:       family,
47:       coachId ?? '∅',
48:       RECONSTRUCT_PAGE_LIMIT,
49:     ],
50:     queryFn: ({ pageParam }) =>
51:       importReviewApi.listEntities(family, {
52:         limit: RECONSTRUCT_PAGE_LIMIT,
53:         ...(pageParam ? { cursor: pageParam } : {}),
54:       }),
55:     initialPageParam: undefined as string | undefined,
56:     getNextPageParam: (last) => last.next_cursor ?? undefined,
57:     enabled: enabled && !!coachId,
58:   });
59: 
60:   const entities = useMemo(
61:     () => dedupeById((query.data?.pages ?? []).flatMap((p) => p.entities)),
62:     [query.data],
63:   );
64:   const reasons = useMemo(
65:     () =>
66:       dedupeById(
67:         (query.data?.pages ?? []).flatMap((p) => p.reasons),
68:         (r) => r.code,
