58:   const data = (response as { data?: unknown }).data;
59:   if (data && typeof data === 'object') {
60:     const fromBody = (data as { request_id?: unknown }).request_id;
61:     if (typeof fromBody === 'string' && fromBody.length > 0) return fromBody;
62:   }
63:   return headerValue((response as { headers?: unknown }).headers, 'x-request-id');
