37:  * Crypto-grade RFC 4122 v4 UUID — the ONE random-id source in the app (R20).
38:  * `generateIdempotencyKey` and the request-correlation id both route through
39:  * here so there is never a second, weaker generator to audit.
40:  */
41: export function randomUuid(): string {
42:   // Single crypto-grade path: Web Crypto API polyfilled by
43:   // react-native-get-random-values (imported at the top of index.ts).
44:   // Works identically in dev builds, Expo Go, and production — no
45:   // Math.random fallback at any layer.
46:   const c = (globalThis as { crypto?: { getRandomValues?: <T extends ArrayBufferView>(array: T) => T } }).crypto;
47:   if (c?.getRandomValues) {
48:     const bytes = new Uint8Array(16);
49:     c.getRandomValues(bytes);
50:     return uuidFromBytes(bytes);
51:   }
52: 
53:   // R19 — no Math.random fallback. If crypto.getRandomValues is unavailable
54:   // (polyfill not imported before this module), throw rather than silently
55:   // emit a weak key.
56:   throw new Error(
57:     'generateIdempotencyKey: crypto.getRandomValues is unavailable. ' +
58:       'Ensure react-native-get-random-values is imported first in index.ts.',
59:   );
60: }
61: 
62: export function generateIdempotencyKey(): string {
63:   return randomUuid();
64: }

