243:  * Metro resolves `.js` and `.jsx` as readily as `.ts`/`.tsx`, so both belong in
244:  * the walk. `src/screenshots/expoSqliteStub.web.js` is the current example: a
245:  * real bundled module — metro.config.js substitutes it for `expo-sqlite` when
246:  * `EXPO_PUBLIC_SCREENSHOT_MODE=1` on web — that a `.tsx?`-only walk never read.
247:  */
248: const BUNDLED_EXTENSIONS = /\.(?:[jt]sx?)$/;
