250: function walk(dir: string, acc: string[] = []): string[] {
251:   for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
252:     const full = path.join(dir, entry.name);
253:     if (entry.isDirectory()) walk(full, acc);
254:     else if (BUNDLED_EXTENSIONS.test(entry.name)) acc.push(full);
255:   }
256:   return acc;
257: }
