259: /**
260:  * The repo-root `.ts`/`.tsx` modules: `index.ts` (the manifest's `main`),
261:  * `App.tsx` — which `index.ts` reaches as `./App` and which is what pulls in
262:  * everything under src/ — and `App.test.tsx`, a test that `isTestFile` classifies
263:  * as such. A src/-only walk read none of them, which left every package reachable
264:  * only from here unguarded; `ENTRYPOINT_ONLY_PACKAGES` names the set.
265:  *
266:  * Root `.js` files are excluded deliberately. `babel.config.js`,
267:  * `metro.config.js`, `jest.setup.js` and `.eslintrc.js` are Node-side build and
268:  * tooling config that Metro never resolves into the app graph, and they load
269:  * devDependencies by design — scanning them would report build tooling as a
270:  * runtime dependency. Non-recursive for the same reason: src/ is walked
271:  * separately, and the root also holds `scripts/`, `node_modules` and `.expo`.
272:  */
273: function rootModules(): string[] {
274:   return fs
275:     .readdirSync(REPO_ROOT, { withFileTypes: true })
276:     .filter((entry) => entry.isFile() && /\.tsx?$/.test(entry.name))
277:     .map((entry) => path.join(REPO_ROOT, entry.name));
278: }
